    private static final int[][] BY_CATEGORY = { HATS, WINGS, BACK, PETS, ARMS, LEGS, AURAS, COSTUMES };

    /** Иконка категории; px — размер одного пикселя иконки в пикселях интерфейса. */
    public static void category(GuiGraphics g, CosmeticCategory c, int x, int y, int px) {
        draw(g, BY_CATEGORY[c.ordinal() % BY_CATEGORY.length], x, y, px);
    }

    public static void coin(GuiGraphics g, int x, int y, int px) {
        draw(g, COIN, x, y, px);
    }

    private static void draw(GuiGraphics g, int[] runs, int x, int y, int px) {
        for (int i = 0; i + 3 < runs.length; i += 4) {
            int rx = x + runs[i] * px, ry = y + runs[i + 1] * px;
            g.fill(rx, ry, rx + runs[i + 2] * px, ry + px, runs[i + 3]);
        }
    }

